import { compileOperatorPattern, PATTERN_WINDOW, PatternError } from "./safe-pattern.js";

/**
 * Commit-message sanitiser (FR-GIT-04, LLD §12.4, T9.3; ADR-0025). Pure and synchronous: it takes the agent's (or the
 * inner agent's) text and returns text with attribution trailers, "generated by" footers, controller / provider / run /
 * session identifiers and session URLs removed, plus a report of rule ids and counts. The report never holds the removed
 * text (FR-GIT-07). The controller adds no line of its own. Rules cannot catch what they do not describe (risk R-14);
 * nothing here touches file contents.
 *
 * Line rules remove the whole line; token rules remove only the matched token (or link). Built-in rules run on a
 * Unicode-NFKC copy of the line with invisible characters already stripped, so a full-width colon or a zero-width space
 * does not hide a trailer. Every built-in expression is linear or has bounded repeats; operator patterns come through
 * {@link compileOperatorPattern} (a restricted subset, see `safe-pattern.ts`) and are applied to windows of at most
 * {@link PATTERN_WINDOW} characters under a wall-clock budget, failing closed.
 */

export const MAX_MESSAGE_CHARS = 65_536;
export { PATTERN_WINDOW };
export const DEFAULT_BUDGET_MS = 1000;
/** Passes until nothing more is removed; removal can join text into a new match, so the result must be a fixed point. */
const MAX_PASSES = 4;
/** Shortest provider-native session id removed by exact match (shorter strings would mangle ordinary words). */
export const MIN_NATIVE_ID_LENGTH = 6;

export class SanitizerError extends Error {
  override readonly name = "SanitizerError";
  constructor(
    readonly code: "MESSAGE_TOO_LONG" | "BUDGET_EXCEEDED" | "NOT_A_FIXED_POINT" | "INVALID_PATTERN",
    message: string,
  ) {
    super(message);
  }
}

export interface SanitizeOptions {
  /** `git.sanitize_patterns` (JavaScript regular-expression sources; validated by `compileOperatorPattern`). */
  readonly operatorPatterns?: readonly string[];
  /** Provider-native session ids of this run (FR-ADP-04), removed by exact match. */
  readonly nativeSessionIds?: readonly string[];
  /** Wall-clock budget for operator-pattern matching (default {@link DEFAULT_BUDGET_MS}). */
  readonly budgetMs?: number;
  readonly now?: () => number;
}

/** `{ rules: { "<rule id>": <count> } }`, the `sanitizer_json` shape of LLD §12.4. Counts only, never removed text. */
export interface SanitizeReport {
  readonly rules: Readonly<Record<string, number>>;
}

export interface SanitizeResult {
  /** Sanitised text without a trailing newline; empty when nothing is left. */
  readonly message: string;
  readonly report: SanitizeReport;
}

/** Rule ids of the built-in set. Operator patterns are reported as `operator.<n>` (1-based, in configuration order). */
export const BUILTIN_RULE_IDS = [
  "trailer.co-author",
  "trailer.generated",
  "trailer.session",
  "trailer.ai-signoff",
  "footer.generated-by",
  "id.controller",
  "id.native-session",
  "url.session",
] as const;

// Product and provider names that make a "generated by" or sign-off line an attribution line. Linear alternation.
const AI_TERMS =
  /\b(?:claude|anthropic|codex|openai|chat-?gpt|gpt-?\d|gemini|antigravity|copilot|cursor|grok|xai|kimi|moonshot|opencode|switchboard|llm|language model|large language|coding (?:agent|assistant)|ai (?:assistant|agent|tool|model|coding|generated)|an? ai|artificial intelligence)\b/iu;

const CO_AUTHOR = /^\s*co-?authored?-?by\s*:/iu;
const GENERATED_TRAILER = /^\s*(?:generated|assisted|authored|created|written|produced|drafted)[- ](?:by|with)\s*:/iu;
// Session-style trailers: vendor-prefixed (`Claude-Session:`), id/url forms, and any trailer keyed by a provider name.
const SESSION_TRAILER = new RegExp(
  [
    String.raw`^\s*[a-z][\w]*-(?:session|conversation)(?:-(?:id|url|link))?\s*:`,
    String.raw`^\s*(?:session|conversation|run|task|thread)-(?:id|url|link)\s*:`,
    String.raw`^\s*[a-z][\w]*-(?:run|task|thread)-id\s*:`,
    String.raw`^\s*(?:x-)?(?:claude|codex|anthropic|openai|chatgpt|cursor|gemini|grok|kimi|opencode|antigravity|switchboard)-[\w-]+\s*:`,
  ].join("|"),
  "iu",
);
const AI_SIGNOFF = /^\s*(?:signed-off|reviewed|authored|created|written|generated|approved)-by\s*:/iu;
// "🤖 Generated with [Claude Code](...)", "Created by ChatGPT", "This commit was written using Cursor": a verb at the
// start (after at most 16 non-letters such as an emoji or bullet), then with/by/using/via within 80 characters.
const FOOTER_HEAD =
  /^[^\p{L}\p{N}]{0,16}(?:this (?:commit|change|patch|pr|pull request|message) (?:was|is) )?(?:generated|created|written|authored|made|built|assisted|co-authored|produced|drafted|implemented)\b.{0,80}?\b(?:with|by|using|via)\b/iu;

const CONTROLLER_ID = /(?<![0-9A-Za-z])(?:sess|run|evt|art|dec|ckp|rte|apv|adv|use|pbd|gcm|gps)_[0-9A-Za-z]{26,}/gu;
const MD_LINK = /\[[^\]\n]{0,200}\]\((https?:\/\/[^)\s]{1,2000})\)/giu;
const BARE_URL = /https?:\/\/[^\s<>"')\]]{1,2000}/giu;

const AI_HOST =
  /(?:^|\.)(?:claude\.ai|claude\.com|chatgpt\.com|chat\.openai\.com|gemini\.google\.com|aistudio\.google\.com|grok\.com|cursor\.com|cursor\.sh|kimi\.com|kimi\.moonshot\.cn|opencode\.ai)$/u;
const AI_HOST_SESSION_PATH = /\/(?:code|chat|c|share|s|sessions?|conversations?|threads?|tasks?|agents?|app)(?:\/|$)/iu;
const SESSION_PATH_OR_QUERY = /(?:session|conversation|thread)s?[_-]?(?:id)?[=/_:-]?[0-9A-Za-z_-]{8,}/iu;

const INVISIBLE = /[­​-‏‪-‮⁠-⁤﻿]/gu;
// biome-ignore lint/suspicious/noControlCharactersInRegex: stripping C0 controls other than tab and newline is the point
const CONTROL = /[\u0000-\u0008\u000B-\u001F\u007F]/gu;

type Counts = Map<string, number>;

function bump(counts: Counts, id: string, by = 1): void {
  counts.set(id, (counts.get(id) ?? 0) + by);
}

function nfkc(line: string): string {
  try {
    return line.normalize("NFKC");
  } catch {
    return line;
  }
}

function builtinLineRule(probe: string): string | undefined {
  if (CO_AUTHOR.test(probe)) return "trailer.co-author";
  if (GENERATED_TRAILER.test(probe)) return "trailer.generated";
  if (SESSION_TRAILER.test(probe)) return "trailer.session";
  if (AI_SIGNOFF.test(probe) && AI_TERMS.test(probe)) return "trailer.ai-signoff";
  if (FOOTER_HEAD.test(probe) && AI_TERMS.test(probe)) return "footer.generated-by";
  return undefined;
}

function isSessionUrl(raw: string): boolean {
  let host = "";
  let rest = raw;
  try {
    const u = new URL(raw);
    host = u.hostname.toLowerCase();
    rest = `${decodeURIComponent(u.pathname)}${u.search}`;
  } catch {
    // Not parseable: judge the raw text, which can only remove more.
  }
  if (host !== "" && AI_HOST.test(host) && AI_HOST_SESSION_PATH.test(rest)) return true;
  CONTROLLER_ID.lastIndex = 0;
  const hasControllerId = CONTROLLER_ID.test(rest);
  CONTROLLER_ID.lastIndex = 0;
  return hasControllerId || SESSION_PATH_OR_QUERY.test(rest);
}

/** Token rules for one line. Returns the new line; counts what was removed. */
function stripTokens(line: string, nativeIds: readonly string[], counts: Counts): string {
  let out = line;
  out = out.replace(MD_LINK, (whole, url: string) => {
    if (!isSessionUrl(url)) return whole;
    bump(counts, "url.session");
    return "";
  });
  out = out.replace(BARE_URL, (url) => {
    if (!isSessionUrl(url)) return url;
    bump(counts, "url.session");
    return "";
  });
  out = out.replace(CONTROLLER_ID, () => {
    bump(counts, "id.controller");
    return "";
  });
  for (const id of nativeIds) {
    if (!out.includes(id)) continue;
    const parts = out.split(id);
    bump(counts, "id.native-session", parts.length - 1);
    out = parts.join("");
  }
  return out;
}

export interface Sanitizer {
  sanitize(message: string): SanitizeResult;
}

/** Compile operator patterns once. Throws {@link SanitizerError} `INVALID_PATTERN` for a pattern outside the subset. */
export function createSanitizer(options: SanitizeOptions = {}): Sanitizer {
  const operator = (options.operatorPatterns ?? []).map((source, i) => {
    try {
      return { id: `operator.${i + 1}`, re: compileOperatorPattern(source) };
    } catch (err) {
      if (err instanceof PatternError) throw new SanitizerError("INVALID_PATTERN", `pattern ${i}: ${err.message}`);
      throw err;
    }
  });
  const nativeIds = [...new Set(options.nativeSessionIds ?? [])].filter((id) => id.length >= MIN_NATIVE_ID_LENGTH);
  const clock = options.now ?? Date.now;
  const budget = options.budgetMs ?? DEFAULT_BUDGET_MS;

  const operatorMatches = (probe: string, deadline: number): string | undefined => {
    for (const { id, re } of operator) {
      for (let at = 0; at < Math.max(probe.length, 1); at += PATTERN_WINDOW) {
        if (clock() > deadline)
          throw new SanitizerError("BUDGET_EXCEEDED", "operator pattern matching exceeded its budget");
        if (re.test(probe.slice(at, at + PATTERN_WINDOW))) return id;
      }
    }
    return undefined;
  };

  const pass = (text: string, counts: Counts, deadline: number): string => {
    const kept: string[] = [];
    for (const raw of text.split("\n")) {
      const probe = nfkc(raw);
      const rule = builtinLineRule(probe) ?? operatorMatches(probe, deadline);
      if (rule !== undefined) {
        bump(counts, rule);
        continue;
      }
      const stripped = stripTokens(raw, nativeIds, counts);
      kept.push(stripped === raw ? raw : stripped.trimEnd());
    }
    return tidy(kept);
  };

  return {
    sanitize(message) {
      if (message.length > MAX_MESSAGE_CHARS) {
        throw new SanitizerError("MESSAGE_TOO_LONG", `message is longer than ${MAX_MESSAGE_CHARS} characters`);
      }
      const deadline = clock() + budget;
      const counts: Counts = new Map();
      let text = tidy(message.replace(/\r\n?/gu, "\n").replace(INVISIBLE, "").replace(CONTROL, "").split("\n"));
      for (let i = 0; i < MAX_PASSES; i++) {
        const before = totalOf(counts);
        text = pass(text, counts, deadline);
        if (totalOf(counts) === before) {
          return {
            message: text,
            report: { rules: Object.fromEntries([...counts].sort(([a], [b]) => a.localeCompare(b))) },
          };
        }
      }
      // Removal kept exposing new matches: refuse rather than publish text we cannot show is clean.
      throw new SanitizerError("NOT_A_FIXED_POINT", "sanitising did not converge");
    },
  };
}

function totalOf(counts: Counts): number {
  let n = 0;
  for (const v of counts.values()) n += v;
  return n;
}

/** Collapse runs of blank lines, drop leading and trailing blank lines, trim trailing blanks on each line. */
function tidy(lines: readonly string[]): string {
  const out: string[] = [];
  for (const l of lines) {
    const line = l.trimEnd();
    if (line === "" && (out.length === 0 || out[out.length - 1] === "")) continue;
    out.push(line);
  }
  while (out.length > 0 && out[out.length - 1] === "") out.pop();
  return out.join("\n");
}

/** One-shot helper for callers that do not reuse a compiled pattern set. */
export function sanitizeMessage(message: string, options: SanitizeOptions = {}): SanitizeResult {
  return createSanitizer(options).sanitize(message);
}
